/* ============ H: CHATS, UPDATES; N: NOTIFICATIONS ============ */
const lastMsg=id=>{const t=S.threads[id];return t&&t.msgs[t.msgs.length-1];};
function threadIds(arch){return Object.keys(S.threads).filter(k=>!isBlocked(k)&&S.threads[k].msgs.length&&(arch?S.archived.has(k):!S.archived.has(k))).sort((a,b)=>(lastMsg(b)?.t||0)-(lastMsg(a)?.t||0));}
function chatRow(id){const t=S.threads[id],m=lastMsg(id);const u=t.unread&&!S.muted.has(id);
 return `<button class="chat-row ${t.unread?'unread':''}" data-go="H02" data-id="${id}">${av(id,'round lg '+(person(id).online?'on':''))}<span class="tx"><b>${esc(pname(id))}</b><small>${m?(m.me?L('Ты: ','You: '):'')+esc(T(m.text)):L('Напиши первым','Say hi first')}</small></span><span class="side2"><time>${m?F.short(m.t):''}</time>${u?`<span class="unr">${t.unread}</span>`:S.muted.has(id)?`<span class="mut">${I.belloff}</span>`:''}</span></button>`;}
SC.H01={root:1,tab:'chats',title:()=>L('Чаты','Chats'),render:(p)=>{const sub=p.sub||'chats';const q=(p.q||'').toLowerCase();
 const head=bar(L('Чаты','Chats'),{actions:`<button class="ibtn ${p.searching?'on':''}" data-act="chatSearch" aria-label="${L('Поиск по чатам','Search chats')}">${I.search}</button>${bellBtn()}`});
 const tabs=seg([['chats',L('Диалоги','Conversations'),C.unreadChats()||''],['updates',L('Обновления','Updates'),C.updates()||'']],sub,'hSub');
 if(sub==='updates')return head+`<div class="view"><div class="wrap">${p.searching?`<div class="inwrap" style="margin-bottom:12px">${I.search}<input class="inp" id="chatQ" placeholder="${L('Поиск по обновлениям','Search updates')}" value="${esc(p.q||'')}" data-in="chatQ" autofocus></div>`:''}${tabs}<p class="note" style="margin:0 0 12px">${L('Объявления событий и сообществ. Ответить лично здесь нельзя — это не личные чаты.','Announcements from events and communities. You can’t reply privately here — they aren’t private chats.')}</p>${S.updates.length?S.updates.filter(u=>!q||(T(u.text)+' '+(u.e?T(EV(u.e)?.title):T(COMMUNITIES[u.c]?.name))).toLowerCase().includes(q)).map(updCard).join('')||empty('search',L('Ничего не найдено','Nothing found'),L('Попробуй другое слово','Try another word')):empty('bell',L('Обновлений нет','No updates'),L('Когда организатор или ведущие что-то объявят, это появится здесь.','When an organiser or host announces something, it shows up here.'))}</div></div>`;
 const fresh=S.matches.filter(m=>(!S.threads[m.p]||!S.threads[m.p].msgs.length)&&!isBlocked(m.p));
 const ids=threadIds(false).filter(id=>!q||pname(id).toLowerCase().includes(q));const arch=threadIds(true).length;
 return head+`<div class="view"><div class="wrap">
 ${p.searching?`<div class="inwrap" style="margin-bottom:12px">${I.search}<input class="inp" id="chatQ" placeholder="${L('Имя собеседника','Name')}" value="${esc(p.q||'')}" data-in="chatQ" autofocus style="min-height:46px"></div>`:''}
 ${fresh.length&&!q?`<div class="sec" style="margin-top:4px">${L('Новые совпадения','New matches')}</div><div class="matches">${fresh.map(m=>`<button data-act="openChat" data-v="${m.p}"><span class="ring2">${av(m.p,'round')}</span>${esc(pname(m.p).split(' ')[0])}</button>`).join('')}</div>`:''}
 ${tabs}
 ${ids.length?firstLoad('chats',ids.map(chatRow).join(''),Array.from({length:4},()=>`<div class="row" style="padding:10px 0"><div class="sk" style="width:58px;height:58px;border-radius:50%"></div><div class="grow"><div class="sk" style="height:13px;width:35%"></div><div class="sk" style="height:11px;width:70%;margin-top:8px"></div></div></div>`).join('')):q?empty('search',L('Никого не нашли','No one found'),L('Ищем только среди твоих диалогов.','We only search your conversations.')):empty('chat',L('Пока тихо','Quiet for now'),L('Личный чат открывается после взаимной симпатии. Посмотри подборку или ответь тем, кому ты нравишься.','A private chat opens after a mutual like. Check Discover or answer people who like you.'),`<button class="btn primary" data-act="toPeople">${L('К людям','To People')}</button>`)}
 ${arch?`<button class="btn text mt8" data-go="H05">${I.archive}${L(`Архив · ${arch}`,`Archive · ${arch}`)}</button>`:''}
 </div></div>`;}};
ACT.hSub=a=>setSub(a.dataset.v);
ACT.toPeople=()=>tab('people',{sub:'discover'});
ACT.chatSearch=()=>{const r=cur();r.p.searching=!r.p.searching;r.p.q='';refresh();$('#chatQ')?.focus();};
IN.chatQ=el=>{cur().p.q=el.value;const pos=el.selectionStart;refresh();const n=$('#chatQ');n.focus();n.setSelectionRange(pos,pos);};
ACT.openUpdate=a=>{const u=S.updates.find(x=>x.id===a.dataset.v);u.read=true;if(u.e)go('E03',{id:u.e});else go('C03',{id:u.c});};

/* H02 — conversation */
SC.H02={title:p=>pname(p.id),valid:p=>!!PEOPLE[p.id]&&(isMatch(p.id)||!!S.threads[p.id]?.ended)&&!isBlocked(p.id),render:(p,r)=>{const id=p.id;const t=S.threads[id]||(S.threads[id]={msgs:[],unread:0});
 if(t.unread){t.unread=0;}
 const sh=shared(id);const g=S.reqOut.find(x=>x.p===id&&['partial','granted'].includes(x.status)&&x.until>Date.now());const mine=S.sharedByMe.find(x=>x.p===id);const m=S.matches.find(x=>x.p===id);
 const pills=[`<button class="pill hot" data-go="P05" data-id="${id}">${ic('spark',13)}${esc(sharedSummary(id))}</button>`,g?`<button class="pill ok" data-go="P08" data-id="${id}">${I.unlock}${L('Тебе открыт профиль','Profile shared with you')}</button>`:`<button class="pill" data-act="reqAccess" data-v="${id}">${I.lock}${L('Расширенный профиль закрыт','Private profile closed')}</button>`,mine?`<span class="pill v">${I.eye}${L('Ты открыл(а) доступ','You shared access')}</span>`:''].join('');
 let lastDay='';const msgs=t.msgs.map((x,i)=>{const day=F.date(x.t);const sep=day!==lastDay?(lastDay=day,`<div class="daysep">${Date.now()-x.t<DAY&&new Date(x.t).getDate()===new Date().getDate()?L('Сегодня','Today'):day}</div>`):'';
  return sep+`<div class="msg ${x.me?'me':''} ${x.status||''}">${esc(T(x.text))}${x.me?`<div class="st">${F.time(x.t)}${x.status==='sending'?I.clock:x.status==='failed'?I.alert:I.check}</div>`:''}</div>${x.status==='failed'?`<button class="msg-retry" data-act="retryMsg" data-v="${i}">${I.undo}${L('Не отправлено · Повторить','Not sent · Retry')}</button>`:''}`;}).join('');
 const ice=!t.msgs.length?`<div class="sec">${L('С чего начать','Conversation starters')}</div><div class="chips">${(sh.match.length?sh.match.slice(0,2).map(tp=>L(`Как ты пришёл(ла) к теме «${topic(tp)}»?`,`How did you get into ${topic(tp)}?`)):[]).concat([L('Что тебе сейчас интересно изучить?','What would you like to explore right now?'),L('Как тебе удобнее общаться?','How do you prefer to keep in touch?')]).map(x=>`<button class="chip wrap" data-act="ice">${esc(x)}</button>`).join('')}</div>`:'';
 const ended=t.ended||!isMatch(id);
 return `<header class="bar solid"><button class="ibtn ghost" data-back aria-label="${L('Назад','Back')}">${I.back}</button><button class="row grow" style="gap:10px;text-align:left;min-width:0" data-go="P01" data-id="${id}">${av(id,'sm round '+(person(id).online?'on':''))}<span style="display:grid;min-width:0"><b style="font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(pname(id))}</b><small style="font-size:12px;color:${person(id).online?'var(--mint)':'var(--mute)'}">${t.pair?L('общий диалог пары','shared couple chat'):esc(presence(id))}</small></span></button><button class="ibtn ghost" data-act="chatMenu" data-v="${id}" aria-label="${L('Информация о диалоге','Conversation details')}">${I.more}</button></header>
 <div class="view nodock ${ended?'':'cta1'}"><div class="wrap"><div class="chat-ctx">${pills}</div>
 <div class="msgs" id="msgs"><div class="msg sys">${m?L(`Взаимная симпатия ${F.rel(m.t)}. Здесь только вы двое.`,`Mutual like ${F.rel(m.t)}. Just the two of you here.`):''}</div>${msgs}${S.ui.typing===id?`<div class="typing"><i></i><i></i><i></i></div>`:''}</div>${ice}
 ${ended?`<div class="alert mt16">${I.block}<span><b>${L('Контакт прекращён','Connection ended')}</b>${L('Новые сообщения недоступны. История осталась у тебя.','No new messages. The history stays with you.')}</span></div>`:''}
 </div></div>${ended?'':`<div class="inputbar"><button class="ibtn ghost" data-act="attach" aria-label="${L('Вложение','Attach')}">${I.plus}</button><textarea id="msgIn" rows="1" placeholder="${L('Сообщение','Message')}" aria-label="${L('Сообщение','Message')}" data-in="grow" data-enter="send">${esc(r.f.msgIn||'')}</textarea><button class="ibtn send" data-act="send" aria-label="${L('Отправить','Send')}" ${(r.f.msgIn||'').trim()?'':'disabled'}>${I.send}</button></div>`}`;},
 after:(p)=>{const v=$('#main .view');if(v)v.scrollTop=v.scrollHeight;renderSide();}};
ACT.ice=a=>{const el=$('#msgIn');el.value=a.textContent;IN.grow(el);el.focus();};
ACT.send=()=>{const el=$('#msgIn');if(!el)return;const v=el.value.trim();if(!v)return;if(v.length>2000){toast(L('Слишком длинное сообщение: максимум 2000 символов','Message too long: 2000 characters max'),{type:'err'});return;}
 const id=cur().p.id;const t=S.threads[id];if(!isMatch(id)||isBlocked(id)||t.ended)return;const owner=S,session=S.session;const live=()=>S===owner&&S.session===session&&!isBlocked(id)&&isMatch(id)&&S.threads[id]===t&&!t.ended;const msg={me:1,text:{ru:v,en:v},t:Date.now(),status:'sending'};t.msgs.push(msg);cur().f.msgIn='';refresh();
 net(400).then(()=>{if(!live())return;msg.status='';if(cur().id==='H02')refresh();maybePush();
  if(!t.replied&&!t.pair){t.replied=1;setTimeout(()=>{if(!live())return;S.ui.typing=id;if(cur().id==='H02'&&cur().p.id===id)refresh();setTimeout(()=>{if(!live())return;S.ui.typing=null;S.archived.delete(id);t.msgs.push({me:0,text:{ru:'Интересный вопрос! Дай подумать пару минут 🙂',en:'Good question! Give me a couple of minutes 🙂'},t:Date.now()});if(cur().id==='H02'&&cur().p.id===id)refresh();else{t.unread=(t.unread||0)+1;renderSide();toast(L(`${pname(id)}: новое сообщение`,`${pname(id)}: new message`),{action:{label:L('Открыть','Open'),fn:()=>openChat(id)}});}},1800);},900);}
 }).catch(()=>{if(!live())return;msg.status='failed';if(cur().id==='H02')refresh();toast(L('Сообщение не отправлено. Текст сохранён','Message not sent. Your text is kept'),{type:'err'});});};
ACT.retryMsg=a=>{const id=cur().p.id;if(!isMatch(id)||isBlocked(id)||S.threads[id]?.ended)return;const owner=S;const t=S.threads[id];const msg=t.msgs[+a.dataset.v];msg.status='sending';refresh();net(400).then(()=>{if(S!==owner||!isMatch(id)||isBlocked(id)||t.ended)return;msg.status='';if(cur().id==='H02'&&cur().p.id===id)refresh();}).catch(()=>{if(S!==owner||isBlocked(id)||t.ended)return;msg.status='failed';refresh();toast(NETFAIL(),{type:'err'});});};
ACT.attach=()=>sheet(()=>({title:L('Отправить','Send'),body:`<div class="card list">${linkRow({act:'attPick',v:'photo',icon:'image',tone:'v',title:L('Фото','Photo'),sub:L('Обычное фото из галереи','A regular photo from your gallery'),noChev:1})}${linkRow({act:'attPick',v:'private',icon:'timer',tone:'l',title:L('Приватное фото','Private photo'),sub:L('Откроется на 24 часа, с водяным знаком','Opens for 24 hours, watermarked'),noChev:1})}${linkRow({act:'attPick',v:'cam',icon:'camera',title:L('Камера','Camera'),noChev:1})}</div><p class="note mt12">${L('Откровенные фото доступны только после проверки возраста у обоих. Мы не можем полностью запретить скриншоты.','Explicit photos are available only once both of you are age-verified. We can’t fully prevent screenshots.')}</p>`}));
ACT.attPick=a=>{closeSheet(true);if(!isMatch(cur().p.id)||isBlocked(cur().p.id)||S.threads[cur().p.id]?.ended)return;if(a.dataset.v==='private'&&person(cur().p.id).verified!==true){toast(L('Собеседник ещё не подтвердил возраст.','The recipient has not verified their age.'),{type:'warn'});return;}if(a.dataset.v==='private'&&!needAge(()=>ACT.attPick(a)))return;const id=cur().p.id;run(null,()=>{S.threads[id].msgs.push({me:1,text:a.dataset.v==='private'?{ru:'Приватное фото · откроется на 24 часа',en:'Private photo · opens for 24 hours'}:{ru:'Фото',en:'Photo'},t:Date.now()});refresh();},{ms:700});};
/* H03/H04 — details, mute, archive, end connection, block */
ACT.chatMenu=a=>{const id=a.dataset.v;sheet(()=>({title:pname(id),lead:av(id,'sm round'),body:`<div class="card list">${linkRow({go:'P01',p:{id},icon:'me',title:L('Профиль','Profile')})}${linkRow({go:'P05',p:{id},icon:'spark',tone:'l',title:L('Что у вас общего','Shared interests')})}${S.sharedByMe.find(x=>x.p===id)?linkRow({act:'revoke',v:id,icon:'lock',tone:'v',title:L('Отозвать мой доступ','Revoke my access'),sub:L('Чат не изменится','The chat stays'),noChev:1}):''}</div>
 <div class="card list mt12">${toggleRow('chatMute',L('Без звука','Mute'),L('Сообщения приходят без уведомлений','Messages arrive silently'),S.muted.has(id),`data-v="${id}"`)}${linkRow({act:'chatArchive',v:id,icon:'archive',title:S.archived.has(id)?L('Вернуть из архива','Unarchive'):L('В архив','Archive'),sub:L('Не удаляет и не блокирует','Doesn’t delete or block'),noChev:1})}</div>
 <div class="card list mt12">${linkRow({act:'endConn',v:id,icon:'x',cls:'danger',title:L('Прекратить общение','End connection'),sub:L('Закрыть новые сообщения','Stop new messages'),noChev:1})}${linkRow({act:'report',v:'person',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}${linkRow({act:'block',v:id,icon:'block',cls:'danger',title:L('Заблокировать','Block'),noChev:1})}</div>`}));};
ACT.chatMute=a=>{const id=a.dataset.v;S.muted.has(id)?S.muted.delete(id):S.muted.add(id);resheet();toast(S.muted.has(id)?L('Без звука','Muted'):L('Звук включён','Unmuted'));};
ACT.chatArchive=a=>{const id=a.dataset.v;const was=S.archived.has(id);was?S.archived.delete(id):S.archived.add(id);closeSheet();if(!was&&cur().id==='H02')back();else refresh();toast(was?L('Диалог возвращён','Conversation restored'):L('Диалог в архиве. Новое сообщение вернёт его','Conversation archived. A new message brings it back'),{type:'ok',action:{label:L('Отменить','Undo'),fn:()=>{was?S.archived.add(id):S.archived.delete(id);refresh();}}});};
ACT.endConn=a=>{const id=a.dataset.v;S.ui.ec={revoke:true};closeSheet(true);sheet(()=>({title:L('Прекратить общение?','End this connection?'),lead:`<span class="ico l">${I.x}</span>`,body:`<p class="lead">${L(`${pname(id)} больше не сможет писать тебе, а ты — ей/ему. История останется у каждого по правилам хранения.`,`${pname(id)} won’t be able to message you, and you won’t message them. Each keeps the history under the retention rules.`)}</p>${S.sharedByMe.find(x=>x.p===id)?`<div class="card list">${toggleRow('ecRevoke',L('Также отозвать мои доступы','Also revoke my access'),L('Расширенный профиль закроется сразу','Your private profile closes immediately'),S.ui.ec.revoke)}</div>`:''}<p class="note mt12">${L('Это не блокировка: профиль и посты останутся видны. Для полной защиты используй «Заблокировать».','This isn’t blocking: profile and posts stay visible. For full protection use Block.')}</p>`,foot:`<button class="btn danger" data-act="ecDo" data-v="${id}">${L('Прекратить общение','End connection')}</button><button class="btn soft" data-act="closeSheet">${L('Отмена','Cancel')}</button>`}));};
ACT.ecRevoke=()=>{S.ui.ec.revoke=!S.ui.ec.revoke;resheet();};
ACT.ecDo=a=>{const id=a.dataset.v;run(a,()=>{S.threads[id].ended=true;S.matches=S.matches.filter(m=>m.p!==id);if(S.ui.ec.revoke)S.sharedByMe=S.sharedByMe.filter(x=>x.p!==id);closeSheet();refresh();},{ok:L('Общение прекращено','Connection ended')});};
SC.H05={title:()=>L('Архив','Archive'),render:()=>{const ids=threadIds(true);return `${bar(L('Архив','Archive'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><p class="note" style="margin:0 0 10px">${L('Архив прячет диалог из списка. Это не блокировка и не удаление.','Archiving hides a conversation from the list. It’s not blocking or deleting.')}</p>${ids.length?ids.map(chatRow).join(''):empty('archive',L('Архив пуст','Archive is empty'))}</div></div>`;}};

/* N01 — one notification centre; counters derive from read state */
const NTXT={match:n=>L(`<b>${pname(n.p)}</b> — это взаимно! Можно написать`,`<b>${pname(n.p)}</b> — it’s mutual! You can chat now`),req:n=>L(`<b>${pname(n.p)}</b> просит открыть расширенный профиль`,`<b>${pname(n.p)}</b> asks to see your private profile`),event:n=>L(`Изменение: <b>${T(EV(n.e).title)}</b> — начало в 19:00`,`Change: <b>${T(EV(n.e).title)}</b> — starts at 19:00`),like:n=>L(`<b>${pname(n.p)}</b> отправил(а) тебе симпатию`,`<b>${pname(n.p)}</b> liked you`),reply:n=>L(`<b>${pname(n.p)}</b> ответил(а) на твою публикацию`,`<b>${pname(n.p)}</b> replied to your post`),grant:n=>L(`<b>${pname(n.p)}</b> открыл(а) тебе расширенный профиль`,`<b>${pname(n.p)}</b> shared a private profile with you`),group:n=>L(`Новые правила в <b>${T(COMMUNITIES[n.c].name)}</b>`,`New rules in <b>${T(COMMUNITIES[n.c].name)}</b>`),evok:n=>L(`Событие <b>${T(EV(n.e).title)}</b> опубликовано`,`Your event <b>${T(EV(n.e).title)}</b> is live`)};
const NICO={match:['heart','l'],req:['lock','v'],event:['cal','a'],like:['heart','l'],reply:['chat','g'],grant:['unlock','g'],group:['users3','v'],evok:['check','g']};
SC.N01={title:()=>L('Уведомления','Notifications'),render:(p)=>{const k=p.k||'all';const acts=['match','req','like','grant','reply'];
 const list=S.notifs.filter(n=>!(n.p&&isBlocked(n.p))&&(k==='all'||(k==='act'?acts.includes(n.type):!acts.includes(n.type))));
 const neu=list.filter(n=>!n.read),old=list.filter(n=>n.read);
 const row=n=>{const [i,t]=NICO[n.type]||['bell',''];return `<button class="nt ${n.read?'':'unread'}" data-act="openNotif" data-v="${n.id}"><span class="ntw">${n.p?av(n.p,''):`<span class="av" style="position:relative">${plate(n.e?EV(n.e).plate:n.c?COMMUNITIES[n.c].plate:'rose')}</span>`}<span class="ico ${t}">${I[i]}</span></span><span class="tx">${NTXT[n.type](n)}<time>${F.rel(n.t)}</time></span>${n.read?'':'<span class="dotu" aria-label="new"></span>'}</button>`;};
 return `${bar(L('Уведомления','Notifications'),{back:1,sm:1,actions:C.notif()?`<button class="btn text auto" data-act="readAll">${L('Прочитать все','Mark all read')}</button>`:`<button class="ibtn ghost" data-go="K05" aria-label="${L('Настройки уведомлений','Notification settings')}">${I.gear}</button>`})}<div class="view nodock"><div class="wrap">
 ${seg([['all',L('Все','All')],['act',L('Люди','People')],['upd',L('События и группы','Events & groups')]],k,'nTab','sm')}
 ${list.length?`${neu.length?`<div class="sec" style="margin-top:4px">${L('Новые','New')}</div>${neu.map(row).join('')}`:''}${old.length?`<div class="sec">${L('Ранее','Earlier')}</div>${old.map(row).join('')}`:''}`:empty('bell',L('Уведомлений нет','No notifications'),L('Здесь появятся симпатии, совпадения, запросы и изменения событий.','Likes, matches, requests and event changes appear here.'))}
 <p class="note mt16">${L('На заблокированном экране мы пишем нейтрально: «Новое уведомление в FetUre» — без имён и тем.','On the lock screen we stay neutral: “New notification in FetUre” — no names or topics.')}</p></div></div>`;}};
ACT.nTab=a=>setP('k',a.dataset.v);
ACT.readAll=()=>{S.notifs.forEach(n=>n.read=true);refresh();toast(L('Все прочитаны','All marked as read'),{type:'ok'});};
ACT.openNotif=a=>{const n=S.notifs.find(x=>x.id===a.dataset.v);n.read=true;const [id,p]=n.go;if(id==='H01')return tab('chats');go(id,p||{});};
/* N02 — ask for push only after a useful action */
function maybePush(){if(S.ui.pushAsked)return;S.ui.pushAsked=1;setTimeout(()=>sheet(()=>({title:L('Не пропустить ответ?','Don’t miss a reply?'),lead:`<span class="ico l">${I.bell}</span>`,body:`<p class="lead">${L('Пришлём уведомление, когда ответят или придёт взаимная симпатия. Текст нейтральный — без имён и подробностей.','We’ll notify you about replies and mutual likes. The text is neutral — no names or details.')}</p><div class="card flat row" style="gap:10px"><img src="${LOGO()}" alt="" style="width:34px"><div class="grow"><b style="font-size:14px">FetUre</b><div class="note">${L('У тебя новое уведомление','You have a new notification')}</div></div></div>`,foot:`<button class="btn primary" data-act="pushOk">${L('Включить уведомления','Turn on notifications')}</button><button class="btn text" data-act="closeSheet">${L('Позже','Later')}</button>`})),900);}
ACT.pushOk=()=>{closeSheet();toast(L('Уведомления включены','Notifications on'),{type:'ok'});};
